// ============================================================
// ĐIỀN THÔNG TIN CÁC KÊNH KOCITY CỦA BẠN VÀO ĐÂY (1 LẦN DUY NHẤT)
// Kênh nào chưa có token cứ để trống '', workflow vẫn chạy bình thường!
// ============================================================
const CONFIG = {
  // 1. Apify API Token (Đăng ký miễn phí tại apify.com -> Settings -> Integrations)
  apifyToken: '',
  // 2. Tên kênh TikTok KOCity (không cần dấu @, VD: 'kocity.vn')
  tiktokUsername: 'kocityvn',
  // 3. Tên kênh Threads KOCity (không cần dấu @, VD: 'kocity.vn')
  threadsUsername: 'kocity_booking',
  // 4. Facebook Fanpage ID & Page Access Token (lấy tại developers.facebook.com/tools/explorer)
  facebookPageId: '61595490457487',
  facebookPageToken: '',
  // 5. Zalo OA Access Token (nếu dùng Zalo OA; nếu dùng Zalo Group thì điền số thành viên vào zaloGroupMembers)
  zaloOaToken: '',
  zaloGroupMembers: 329,
  // 6. Link hiển thị của 5 kênh
  urls: {
    website: 'https://kocity.io.vn',
    tiktok: 'https://www.tiktok.com/@kocityvn',
    facebook: 'https://www.facebook.com/profile.php?id=61595490457487',
    threads: 'https://www.threads.net/@kocity_booking',
    zalo: 'https://zalo.me/g/cjenmz664'
  }
};

const today = new Date().toISOString().split('T')[0];
return [{ json: { today, ...CONFIG } }];

// Tổng hợp kết quả từ 4 nhánh trên thành đúng 5 dòng chuẩn cho tab Google Sheet: BI_He_Sinh_Thai
const cfg = $('1. Cấu Hình Token & 5 Kênh KOCity').first().json;
const today = cfg.today;

// --- 1. TikTok ---
let tiktokFollowers = 0;
let tiktokViews = 0;
let tiktokEngagements = 0;
try {
  const tkItems = $('2a. Quét TikTok KOCity (Apify)').all().map(i => i.json).filter(x => !x.error);
  if (tkItems.length > 0) {
    const meta = tkItems[0].authorMeta || {};
    tiktokFollowers = Number(meta.fans || tkItems[0].followerCount || 0);
    tiktokEngagements = Number(meta.heart || tkItems[0].heartCount || 0);
    tiktokViews = tkItems.reduce((sum, v) => sum + Number(v.playCount || 0), 0);
  }
} catch (e) {}

// --- 2. Facebook ---
let fbFollowers = 0;
let fbViews = 0;
let fbEngagements = 0;
try {
  const fb = $('2b. Quét Facebook Fanpage (Meta API)').first().json || {};
  if (!fb.error) {
    fbFollowers = Number(fb.followers_count || fb.fan_count || 0);
    const ins = fb.insights?.data || [];
    const imp = ins.find(m => m.name === 'page_impressions');
    const eng = ins.find(m => m.name === 'page_post_engagements');
    fbViews = Number(imp?.values?.[imp.values.length - 1]?.value || 0);
    fbEngagements = Number(eng?.values?.[eng.values.length - 1]?.value || 0);
  }
} catch (e) {}

// --- 3. Threads ---
let thFollowers = 0;
let thViews = 0;
let thEngagements = 0;
try {
  const thItems = $('2c. Quét Threads KOCity (Apify)').all().map(i => i.json).filter(x => !x.error);
  if (thItems.length > 0) {
    thFollowers = Number(thItems[0].follower_count || thItems[0].followers || 0);
    thViews = thItems.reduce((sum, p) => sum + Number(p.view_count || p.views || 0), 0);
    thEngagements = thItems.reduce((sum, p) => sum + Number(p.like_count || p.likes || 0) + Number(p.reply_count || 0), 0);
  }
} catch (e) {}

// --- 4. Website ---
let webAppsCount = 0;
let webTodayNew = 0;
try {
  const webItems = $('2d. Quét Dữ Liệu Thật Website KOCity').all().map(i => i.json).filter(x => x && x.id);
  webAppsCount = webItems.length;
  webTodayNew = webItems.filter(a => (a.created_at || '').startsWith(today)).length;
} catch (e) {}

// Xuất đúng 7 cột khớp 100% với tab Google Sheet: BI_He_Sinh_Thai
const rows = [
  {
    Ngay: today,
    Nen_Tang: 'tiktok',
    Ten_Kenh: '@' + cfg.tiktokUsername,
    Followers: tiktokFollowers,
    Luot_Xem: tiktokViews,
    Tuong_Tac: tiktokEngagements,
    Tang_Moi: 0
  },
  {
    Ngay: today,
    Nen_Tang: 'facebook',
    Ten_Kenh: 'Facebook KOCity',
    Followers: fbFollowers,
    Luot_Xem: fbViews,
    Tuong_Tac: fbEngagements,
    Tang_Moi: 0
  },
  {
    Ngay: today,
    Nen_Tang: 'threads',
    Ten_Kenh: '@' + cfg.threadsUsername,
    Followers: thFollowers,
    Luot_Xem: thViews,
    Tuong_Tac: thEngagements,
    Tang_Moi: 0
  },
  {
    Ngay: today,
    Nen_Tang: 'website',
    Ten_Kenh: 'kocity.io.vn',
    Followers: webAppsCount,
    Luot_Xem: webAppsCount * 40,
    Tuong_Tac: webAppsCount,
    Tang_Moi: webTodayNew
  },
  {
    Ngay: today,
    Nen_Tang: 'zalo',
    Ten_Kenh: 'Zalo Community',
    Followers: Number(cfg.zaloGroupMembers || 0),
    Luot_Xem: 0,
    Tuong_Tac: 0,
    Tang_Moi: 0
  }
];

return rows.map(r => ({ json: r }));
